import json
from pathlib import Path
p=Path('editorial15/calendar_q4.json'); rows=json.loads(p.read_text())
def add(date,code,title,year,summary,url,ref,source):
 rows.append(dict(date=date,code=code,title=title,year=year,summary=summary,url=url,source_title=source,evidence='Date et événement explicitement attestés : '+ref,confidence='high'))
add('11-03','DMA','L’indépendance de la Dominique',1978,'La Dominique devient indépendante le 3 novembre 1978. Cette île des Petites Antilles met ainsi fin à sa période d’administration britannique.','https://history.state.gov/countries/dominica','turn227search2','Office of the Historian')
add('11-04','IRN','La prise d’otages de l’ambassade américaine',1979,'Le 4 novembre 1979, des militants iraniens occupent l’ambassade des États-Unis à Téhéran et retiennent son personnel. Cette crise marque durablement les relations entre les deux pays.','https://history.state.gov/departmenthistory/short-history/iraniancrises','turn227search12','Office of the Historian')
add('11-05','GBR','La conspiration des Poudres déjouée',1605,'Le complot prévoyait de faire exploser le Parlement lors de son ouverture le 5 novembre 1605. Découvert la nuit précédente, il échoue ; le Parlement consigne sa découverte dans son journal le 5 novembre.','https://www.parliament.uk/about/living-heritage/evolutionofparliament/parliamentaryauthority/the-gunpowder-plot-of-1605/keydates/october-1605--1606/','turn227search8','Parlement britannique')
add('11-06','USA','L’élection d’Abraham Lincoln',1860,'Abraham Lincoln remporte l’élection présidentielle du 6 novembre 1860. Cette élection intervient dans un pays profondément divisé par l’esclavage, quelques mois avant le déclenchement de la guerre de Sécession.','https://home.nps.gov/liho/learn/historyculture/lincolnchronology.htm','turn228search13','National Park Service')
add('11-07','ZAF','Nelson Mandela est condamné à cinq ans de prison',1962,'Le 7 novembre 1962, Nelson Mandela est condamné pour incitation à la grève et sortie du territoire sans documents valides. Cette peine précède la condamnation à perpétuité du procès de Rivonia.','https://www.nelsonmandela.org/prison-timeline','turn230search1','Nelson Mandela Foundation')
add('11-08','DEU','Le début du putsch de Munich',1923,'Les 8 et 9 novembre 1923, Adolf Hitler et ses alliés tentent un coup de force à Munich. L’échec de cette tentative constitue un épisode important de l’histoire du mouvement nazi avant son accession au pouvoir.','https://encyclopedia.ushmm.org/content/en/article/beer-hall-putsch-munich-putsch','turn228search10','United States Holocaust Memorial Museum')
add('11-09','DEU','L’ouverture du mur de Berlin',1989,'Le soir du 9 novembre 1989, les points de passage du mur de Berlin s’ouvrent. Cet événement symbolise la fin de la division de la ville et précède la réunification allemande.','https://www.bundesregierung.de/breg-de/schwerpunkte/deutsche-einheit/die-mauer-ist-offen--403858','turn228search0','Gouvernement fédéral allemand')
add('11-10','TUR','La mort de Mustafa Kemal Atatürk',1938,'Mustafa Kemal Atatürk meurt à Istanbul le 10 novembre 1938. Premier président de la République turque, il avait joué un rôle central dans sa fondation et ses transformations institutionnelles.','https://www.ktb.gov.tr/EN-118282/ataturk-mustafa-kemal.html','turn230search22','Ministère turc de la Culture')
add('11-11','POL','Le retour de l’indépendance polonaise',1918,'Le 11 novembre 1918, Józef Piłsudski prend le commandement des forces polonaises. La Pologne commémore à cette date le rétablissement de son indépendance après les partages.','https://stat.gov.pl/en/news/national-independance-day-11-november%2C156%2C1.html','turn230search12','Statistics Poland')
add('11-12','TLS','Le massacre de Santa Cruz',1991,'Le 12 novembre 1991, une marche à Dili est réprimée dans le cimetière de Santa Cruz. Ce massacre devient un événement majeur de la mémoire et de la lutte pour l’indépendance timoraises.','https://timor-leste.gov.tl/?lang=en&p=46043&print=1','turn232search0','Gouvernement du Timor-Leste')
add('11-13','FRA','Les attentats de Paris et Saint-Denis',2015,'Le 13 novembre 2015, des attentats frappent Paris et Saint-Denis, notamment le Bataclan, des terrasses et les abords du Stade de France. La date est consacrée à la mémoire des victimes.','https://www.elysee.fr/emmanuel-macron/2025/11/13/commemoration-des-10-ans-des-attentats-du-13-novembre-2015','turn232search3','Présidence de la République française')
add('11-14','USA','Le lancement d’Apollo 12',1969,'Apollo 12 est lancé le 14 novembre 1969 depuis la Floride. La mission réalise ensuite le deuxième alunissage habité du programme Apollo.','https://science.nasa.gov/resource/apollo-12/','turn231search6','NASA')
add('11-16','GBR','L’adoption de la Constitution de l’UNESCO à Londres',1945,'Le 16 novembre 1945, la Constitution de l’UNESCO est adoptée à Londres. Cette organisation internationale entend contribuer à la paix par l’éducation, les sciences et la culture.','https://www.unesco.org/en/legal-affairs/constitution?hub=70224','turn231search1','UNESCO')
add('11-17','CZE','Le début de la révolution de Velours',1989,'La manifestation du 17 novembre 1989 à Prague ouvre une série de mobilisations contre le régime communiste. La révolution de Velours conduit au retour du pluralisme politique en Tchécoslovaquie.','https://mzv.gov.cz/london/en/what_s_new/x17_november_1989_31_years_of_freedom.html','turn235search1','Ministère tchèque des Affaires étrangères')
add('11-18','LVA','La proclamation de la République de Lettonie',1918,'La République de Lettonie est proclamée le 18 novembre 1918. Le Conseil du peuple constitue alors la première institution législative du nouvel État.','https://www.saeima.lv/en/about-saeima/history-of-the-legislature','turn235search3','Parlement letton')
add('11-19','USA','Le discours de Gettysburg',1863,'Le 19 novembre 1863, Abraham Lincoln prononce son discours de Gettysburg lors de l’inauguration d’un cimetière militaire. Ce texte bref relie la guerre de Sécession aux principes de liberté et d’égalité.','https://www.loc.gov/item/today-in-history/november-19/','turn233search4','Library of Congress')
add('11-20','MEX','Le début de la Révolution mexicaine',1910,'Le 20 novembre 1910 est la date fixée par Francisco I. Madero pour le soulèvement contre le gouvernement de Porfirio Díaz. Elle marque le commencement commémoré de la Révolution mexicaine.','https://www.gob.mx/segob/es/articulos/revolucion-mexicana-el-gran-movimiento-social-del-siglo-xx?idiom=en','turn233search12','Ministère mexicain de l’Intérieur')
add('11-21','BIH','Les accords de Dayton sont paraphés',1995,'Le 21 novembre 1995, les accords négociés à Dayton sont paraphés. Ils organisent le règlement de la guerre en Bosnie-Herzégovine ; leur signature formelle aura lieu à Paris en décembre.','https://2009-2017.state.gov/p/eur/rls/or/dayton/52599.htm','turn235search6','Département d’État — texte de l’accord')
add('11-22','LBN','L’indépendance du Liban',1943,'Le Liban commémore son indépendance le 22 novembre 1943. Cette date renvoie à l’aboutissement de la crise politique opposant les dirigeants libanais aux autorités du mandat français.','https://www.lebarmy.gov.lb/en/content/foreword-minister-defense','turn235search9','Armée libanaise — ministre de la Défense')
add('11-23','GEO','La révolution des Roses',2003,'Le 23 novembre 2003, les manifestations à Tbilissi conduisent à la démission d’Edouard Chevardnadze. Ce tournant politique géorgien est connu sous le nom de révolution des Roses.','https://odihr.osce.org/odihr/elections/3628','turn238search2','OSCE')
add('11-24','GBR','La publication de L’Origine des espèces',1859,'La première édition de L’Origine des espèces paraît le 24 novembre 1859. Charles Darwin y développe son explication de l’évolution par la sélection naturelle, un jalon majeur de l’histoire des sciences.','https://darwin-editorial.darwinproject.ac.uk/letters/darwins-works-letters/rewriting-origin-later-editions','turn242search17','Darwin Correspondence Project — université de Cambridge')
add('11-25','SUR','L’indépendance du Suriname',1975,'Le Suriname accède à l’indépendance le 25 novembre 1975. Cet État d’Amérique du Sud était auparavant lié aux Pays-Bas.','https://www.fordlibrarymuseum.gov/library/document/0248/whpr19751125-006.pdf','turn238search8','Gerald R. Ford Presidential Library — communiqué original')
add('11-26','IND','L’Inde adopte sa Constitution',1949,'L’Assemblée constituante adopte la Constitution indienne le 26 novembre 1949. Son entrée en vigueur, distincte de cette adoption, aura lieu le 26 janvier 1950.','https://sansad.in/uploads/jpi_march_2022_d297f2a085.pdf?updated_at=2022-09-13T17%3A54%3A31.346Z','turn238search9','Parlement indien')
add('11-27','SWE','Le testament à l’origine des prix Nobel',1895,'Le 27 novembre 1895, l’inventeur suédois Alfred Nobel signe le testament qui affecte l’essentiel de sa fortune à des prix. Ces récompenses concernent les sciences, la littérature et la paix.','https://www.nobelprize.org/prizes/list/nobel-prize-facts/','turn242search1','Fondation Nobel')
add('11-28','ALB','L’Albanie proclame son indépendance',1912,'Le 28 novembre 1912, l’indépendance albanaise est proclamée à Vlora. Cette décision intervient dans le contexte des guerres balkaniques et du recul de l’Empire ottoman.','https://www.muzeu-fa.gov.al/english/independence-era/14-pavaresia','turn248search11','Musée des forces armées albanaises')
add('11-29','PSE','La Palestine devient État observateur à l’ONU',2012,'Le 29 novembre 2012, l’Assemblée générale des Nations unies accorde à la Palestine le statut d’État observateur non membre. Ce statut ne correspond pas à une admission comme membre de plein droit.','https://www.un.org/unispal/document/auto-insert-187149/','turn242search11','Nations unies — résolution de l’Assemblée générale')
add('11-30','BRB','L’indépendance de la Barbade',1966,'La Barbade devient un État indépendant le 30 novembre 1966. Cette date marque la fin de sa période coloniale britannique.','https://history.state.gov/countries/barbados','turn244search0','Office of the Historian')
add('12-01','ROU','L’assemblée d’Alba Iulia',1918,'Le 1er décembre 1918, l’assemblée d’Alba Iulia se prononce pour l’union de la Transylvanie avec la Roumanie. Cette date est devenue la fête nationale roumaine.','https://english.mapn.ro/cpresa/5056_DEFENCE-MINISTERS-MESSAGE--ON-THE-OCCASION-OF-THE-CELEBRATION-OF-ROMANIAS-NATIONAL-DAY-AND-ITS-CENTENNIAL','turn248search16','Ministère roumain de la Défense')
add('12-02','ARE','La naissance des Émirats arabes unis',1971,'Les Émirats arabes unis sont fondés le 2 décembre 1971. La fédération rassemble initialement six émirats ; Ras el-Khaïmah la rejoint en 1972.','https://u.ae/en/about-the-uae/founders-of-the-union','turn244search2','Portail officiel des Émirats arabes unis')
add('12-03','IND','La catastrophe industrielle de Bhopal',1984,'Dans la nuit du 2 au 3 décembre 1984, une fuite de gaz toxique survient dans une usine de Bhopal. La catastrophe entraîne des conséquences humaines et sanitaires durables.','https://www.hse.gov.uk/comah/sragtech/caseuncarbide84.htm','turn248search1','Health and Safety Executive')
add('12-04','IND','L’opération navale Trident',1971,'Le 4 décembre 1971, la marine indienne mène l’opération Trident contre des installations et navires pakistanais à Karachi. Cette opération de la guerre indo-pakistanaise est commémorée par la journée de la marine indienne.','https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=1880672&lang=2&reg=48','turn248search5','Press Information Bureau — gouvernement indien')
p.write_text(json.dumps(sorted(rows,key=lambda r:r['date']),ensure_ascii=False,indent=2)+'\n')
